<?php
require_once '../config/auth.php';require_role('guru');$pdo=db();$gid=(int)user_reference();$error='';
$q=$pdo->prepare('SELECT j.id_jadwal,j.id_kelas,k.nama_kelas,mp.nama_mapel,j.hari,j.jam_mulai FROM jadwal j JOIN kelas k ON k.id_kelas=j.id_kelas JOIN mata_pelajaran mp ON mp.id_mapel=j.id_mapel WHERE j.id_guru=? ORDER BY FIELD(j.hari,"Senin","Selasa","Rabu","Kamis","Jumat"),j.jam_mulai');$q->execute([$gid]);$schedules=$q->fetchAll();
$selected=(int)($_POST['id_jadwal']??$_GET['id_jadwal']??0);$date=$_POST['tanggal']??$_GET['tanggal']??date('Y-m-d');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'save';if($action==='delete'){$q=$pdo->prepare('DELETE FROM absensi WHERE id_absen=? AND created_by=?');$q->execute([(int)$_POST['id_absen'],$gid]);flash('success','Catatan absensi dihapus.');}else{$q=$pdo->prepare('SELECT id_kelas FROM jadwal WHERE id_jadwal=? AND id_guru=?');$q->execute([$selected,$gid]);$schedule=$q->fetch();$q2=$pdo->prepare('SELECT 1 FROM siswa WHERE nis=? AND id_kelas=?');$q2->execute([$_POST['nis'],$schedule['id_kelas']??0]);if(!$schedule||!$q2->fetch())throw new RuntimeException('Siswa bukan bagian dari jadwal Anda.');$q=$pdo->prepare('INSERT INTO absensi(tanggal,nis,id_jadwal,status,keterangan,created_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),keterangan=VALUES(keterangan),created_by=VALUES(created_by)');$q->execute([$date,$_POST['nis'],$selected,$_POST['status'],trim($_POST['keterangan']??'')?:null,$gid]);flash('success','Absensi berhasil disimpan.');}redirect('absen.php?id_jadwal='.$selected.'&tanggal='.$date);}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Absensi gagal disimpan.';}}
$students=[];if($selected){$q=$pdo->prepare('SELECT s.nis,s.nama_siswa,a.id_absen,a.status,a.keterangan FROM jadwal j JOIN siswa s ON s.id_kelas=j.id_kelas LEFT JOIN absensi a ON a.nis=s.nis AND a.id_jadwal=j.id_jadwal AND a.tanggal=? WHERE j.id_jadwal=? AND j.id_guru=? ORDER BY s.nama_siswa');$q->execute([$date,$selected,$gid]);$students=$q->fetchAll();}$page_title='Absensi Siswa';require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php';
?><h2>Absensi Siswa</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-3 mb-4"><form method="get" class="row g-2 align-items-end"><div class="col-md-6"><label class="form-label">Jadwal</label><select class="form-select" name="id_jadwal" required><option value="">Pilih jadwal</option><?php foreach($schedules as $s):?><option value="<?=$s['id_jadwal']?>" <?=($selected===$s['id_jadwal'])?'selected':''?>><?=e($s['hari'].' '.substr($s['jam_mulai'],0,5).' · '.$s['nama_mapel'].' · '.$s['nama_kelas'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Tanggal</label><input class="form-control" type="date" name="tanggal" value="<?=e($date)?>" required></div><div class="col-md-2"><button class="btn btn-primary w-100">Tampilkan</button></div></form></div><?php if($selected&&$students):?><div class="card p-3"><h5>Daftar Kehadiran · <?=e($date)?></h5><div class="table-responsive"><table class="table"><thead><tr><th>NIS</th><th>Nama</th><th>Status</th><th>Keterangan</th><th>Aksi</th></tr></thead><tbody><?php foreach($students as $s):?><tr><form method="post"><?=csrf_field()?><input type="hidden" name="id_jadwal" value="<?=$selected?>"><input type="hidden" name="tanggal" value="<?=e($date)?>"><input type="hidden" name="nis" value="<?=e($s['nis'])?>"><td><?=e($s['nis'])?></td><td><?=e($s['nama_siswa'])?></td><td><select class="form-select form-select-sm" name="status"><?php foreach(['Hadir','Izin','Sakit','Alpa'] as $st):?><option <?=($s['status']??'Hadir')===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></td><td><input class="form-control form-control-sm" name="keterangan" value="<?=e($s['keterangan']??'')?>"></td><td class="text-nowrap"><button class="btn btn-sm btn-success" name="action" value="save">Simpan</button><?php if($s['id_absen']):?><input type="hidden" name="id_absen" value="<?=$s['id_absen']?>"><button class="btn btn-sm btn-outline-danger" name="action" value="delete">Hapus</button><?php endif;?></td></form></tr><?php endforeach;?></tbody></table></div></div><?php elseif($selected):?><div class="alert alert-info">Tidak ada siswa pada kelas ini.</div><?php endif;?><?php require '../includes/footer.php';
